content:
:root {
  --bg-main: #0f172a;
  --bg-gradient: radial-gradient(circle at 50% 0%, #1e293b 0%, #0f172a 100%);
  --card-bg: rgba(30, 41, 59, 0.7);
  --card-border: rgba(255, 255, 255, 0.1);
  --display-bg: rgba(15, 23, 42, 0.85);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --btn-num-bg: #334155;
  --btn-num-hover: #475569;
  --btn-num-active: #1e293b;
  --btn-num-text: #f8fafc;

  --btn-fn-bg: #475569;
  --btn-fn-hover: #64748b;
  --btn-fn-active: #334155;
  --btn-fn-text: #cbd5e1;

  --btn-op-bg: #ea580c;
  --btn-op-hover: #f97316;
  --btn-op-active: #c2410c;
  --btn-op-text: #ffffff;

  --btn-eq-bg: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  --btn-eq-hover: linear-gradient(135deg, #0369a1 0%, #1d4ed8 100%);
  --btn-eq-active: linear-gradient(135deg, #075985 0%, #1e40af 100%);
  --btn-eq-text: #ffffff;

  --radius-xl: 24px;
  --radius-lg: 16px;
  --radius-md: 12px;
  --radius-sm: 8px;

  --shadow-card: 0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.08);
  --shadow-btn: 0 4px 6px -1px rgba(0, 0, 0, 0.2), 0 2px 4px -2px rgba(0, 0, 0, 0.15);
  --shadow-inset: inset 0 2px 4px 0 rgba(0, 0, 0, 0.25);

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "SF Mono", "Fira Code", Menlo, Monaco, Consolas, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-main);
  background-image: var(--bg-gradient);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
}

/* 全体コンテナ */
.calculator-container {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  justify-content: center;
  gap: 1.5rem;
  width: 100%;
  max-width: 860px;
  margin: auto;
  user-select: none;
}

/* 電卓本体カード */
.calculator-card {
  flex: 1 1 360px;
  max-width: 420px;
  background: var(--card-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-xl);
  padding: 1.75rem;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ヘッダー */
.calculator-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 0.25rem;
}

.calculator-title {
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.calculator-title::before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #38bdf8;
  box-shadow: 0 0 8px #38bdf8;
}

/* ディスプレイパネル */
.display-panel {
  background: var(--display-bg);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-lg);
  padding: 1rem 1.25rem;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-end;
  min-height: 100px;
  box-shadow: var(--shadow-inset);
  overflow: hidden;
  word-break: break-all;
}

.history-text {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  color: var(--text-muted);
  min-height: 1.4rem;
  margin-bottom: 0.25rem;
  text-align: right;
  max-width: 100%;
  overflow-x: auto;
  white-space: nowrap;
}

.current-value {
  font-family: var(--font-mono);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--text-main);
  line-height: 1.2;
  text-align: right;
  max-width: 100%;
  overflow-x: auto;
  white-space: nowrap;
}

/* キーパッドグリッド */
.keypad-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.75rem;
}

/* ボタンベース */
.btn-calc {
  font-family: var(--font-family);
  font-size: 1.25rem;
  font-weight: 600;
  border: none;
  outline: none;
  border-radius: var(--radius-md);
  height: 60px;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all 0.15s ease;
  box-shadow: var(--shadow-btn);
  touch-action: manipulation;
}

.btn-calc:active {
  transform: scale(0.95);
}

/* 数字ボタン */
.btn-number {
  background: var(--btn-num-bg);
  color: var(--btn-num-text);
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.btn-number:hover {
  background: var(--btn-num-hover);
}

.btn-number:active {
  background: var(--btn-num-active);
}

/* 機能ボタン (C, AC, +/-, %) */
.btn-function {
  background: var(--btn-fn-bg);
  color: var(--btn-fn-text);
  font-weight: 600;
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.btn-function:hover {
  background: var(--btn-fn-hover);
}

.btn-function:active {
  background: var(--btn-fn-active);
}

/* 演算子ボタン (+, -, ×, ÷) */
.btn-operator {
  background: var(--btn-op-bg);
  color: var(--btn-op-text);
  font-size: 1.4rem;
}

.btn-operator:hover {
  background: var(--btn-op-hover);
  box-shadow: 0 0 12px rgba(234, 88, 12, 0.4);
}

.btn-operator:active {
  background: var(--btn-op-active);
}

/* イコールボタン */
.btn-equals {
  background: var(--btn-eq-bg);
  color: var(--btn-eq-text);
  font-size: 1.4rem;
}

.btn-equals:hover {
  background: var(--btn-eq-hover);
  box-shadow: 0 0 14px rgba(37, 99, 235, 0.5);
}

.btn-equals:active {
  background: var(--btn-eq-active);
}

/* 0ボタン（2列分拡張） */
.btn-zero {
  grid-column: span 2;
  justify-content: flex-start;
  padding-left: 1.75rem;
}

/* 履歴パネル */
.history-panel {
  flex: 1 1 280px;
  max-width: 360px;
  background: var(--card-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-xl);
  padding: 1.5rem;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  min-height: 480px;
}

.history-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--card-border);
  margin-bottom: 0.75rem;
}

.clear-history-btn {
  background: transparent;
  color: var(--text-dim);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 0.35rem 0.65rem;
  font-size: 0.8rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
}

.clear-history-btn:hover {
  color: #f87171;
  border-color: rgba(248, 113, 113, 0.4);
  background: rgba(248, 113, 113, 0.1);
}

/* 履歴リスト */
.history-list {
  list-style: none;
  overflow-y: auto;
  max-height: 380px;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  padding-right: 0.25rem;
}

.history-list::-webkit-scrollbar {
  width: 5px;
}

.history-list::-webkit-scrollbar-track {
  background: transparent;
}

.history-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 4px;
}

.history-item {
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: var(--radius-md);
  padding: 0.65rem 0.85rem;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  cursor: pointer;
  transition: all 0.2s ease;
}

.history-item:hover {
  background: rgba(51, 65, 85, 0.5);
  border-color: rgba(56, 189, 248, 0.3);
  transform: translateX(-2px);
}

.history-expression {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--text-muted);
  word-break: break-all;
  text-align: right;
}

.history-result {
  font-family: var(--font-mono);
  font-size: 1.15rem;
  font-weight: 700;
  color: #38bdf8;
  word-break: break-all;
  text-align: right;
  margin-top: 0.2rem;
}

.history-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1;
  color: var(--text-dim);
  font-size: 0.9rem;
  text-align: center;
  padding: 2rem 1rem;
}

/* レスポンシブ対応 (スマートフォン・幅狭画面) */
@media (max-width: 768px) {
  body {
    padding: 0.5rem;
    align-items: flex-start;
  }

  .calculator-container {
    flex-direction: column;
    align-items: center;
    gap: 1rem;
  }

  .calculator-card,
  .history-panel {
    max-width: 100%;
    width: 100%;
  }

  .calculator-card {
    padding: 1.25rem;
  }

  .btn-calc {
    height: 54px;
    font-size: 1.15rem;
  }

  .current-value {
    font-size: 1.85rem;
  }

  .history-panel {
    min-height: auto;
  }

  .history-list {
    max-height: 220px;
  }
}

import { useState, useEffect, useCallback } from 'react';
import './index.css';

interface CalculationHistory {
  id: string;
  expression: string;
  result: string;
}

export default function App() {
  const [currentValue, setCurrentValue] = useState<string>('0');
  const [previousValue, setPreviousValue] = useState<number | null>(null);
  const [operator, setOperator] = useState<string | null>(null);
  const [waitingForNewValue, setWaitingForNewValue] = useState<boolean>(false);
  const [expressionDisplay, setExpressionDisplay] = useState<string>('');
  const [history, setHistory] = useState<CalculationHistory[]>([]);

  // 小数点計算の浮動小数点誤差を解消するフォーマット関数
  const formatResult = (num: number): string => {
    if (!isFinite(num)) {
      return 'エラー';
    }
    const fixed = parseFloat(num.toPrecision(12));
    const stringVal = fixed.toString();
    if (stringVal.includes('e')) {
      return stringVal;
    }
    // 表示桁数が長すぎる場合の安全なクリップ
    if (stringVal.length > 14) {
      return fixed.toExponential(6);
    }
    return stringVal;
  };

  // 数字入力処理
  const handleDigit = useCallback((digit: string) => {
    setCurrentValue((prev) => {
      if (waitingForNewValue) {
        setWaitingForNewValue(false);
        return digit;
      }
      if (prev === '0') {
        return digit;
      }
      if (prev.length >= 14) {
        return prev;
      }
      return prev + digit;
    });
  }, [waitingForNewValue]);

  // 小数点入力処理
  const handleDecimal = useCallback(() => {
    setCurrentValue((prev) => {
      if (waitingForNewValue) {
        setWaitingForNewValue(false);
        return '0.';
      }
      if (prev.includes('.')) {
        return prev;
      }
      return prev + '.';
    });
  }, [waitingForNewValue]);

  // 符号反転 (+/-)
  const handleToggleSign = useCallback(() => {
    setCurrentValue((prev) => {
      if (prev === '0' || prev === 'エラー') return prev;
      if (prev.startsWith('-')) {
        return prev.slice(1);
      }
      return '-' + prev;
    });
  }, []);

  // パーセント (%)
  const handlePercent = useCallback(() => {
    setCurrentValue((prev) => {
      const num = parseFloat(prev);
      if (isNaN(num)) return '0';
      const res = num / 100;
      return formatResult(res);
    });
  }, []);

  // 二項演算実行
  const executeOperation = (prev: number, current: number, op: string): number => {
    switch (op) {
      case '+':
        return prev + current;
      case '-':
        return prev - current;
      case '×':
        return prev * current;
      case '÷':
        if (current === 0) {
          return Infinity;
        }
        return prev / current;
      default:
        return current;
    }
  };

  // 演算子ボタン押下 (+, -, ×, ÷)
  const handleOperator = useCallback((op: string) => {
    const currentNum = parseFloat(currentValue);

    if (previousValue === null) {
      setPreviousValue(currentNum);
      setOperator(op);
      setExpressionDisplay(`${currentValue} ${op}`);
      setWaitingForNewValue(true);
    } else if (operator && !waitingForNewValue) {
      const result = executeOperation(previousValue, currentNum, operator);
      const formattedResult = formatResult(result);

      if (formattedResult === 'エラー') {
        setCurrentValue('エラー');
        setPreviousValue(null);
        setOperator(null);
        setExpressionDisplay('');
        setWaitingForNewValue(true);
        return;
      }

      const newPrevNum = parseFloat(formattedResult);
      setPreviousValue(newPrevNum);
      setCurrentValue(formattedResult);
      setOperator(op);
      setExpressionDisplay(`${formattedResult} ${op}`);
      setWaitingForNewValue(true);
    } else {
      // 演算子の置き換え
      setOperator(op);
      setExpressionDisplay(`${currentValue} ${op}`);
    }
  }, [currentValue, operator, previousValue, waitingForNewValue]);

  // イコール押下
  const handleEquals = useCallback(() => {
    if (previousValue === null || operator === null) {
      return;
    }

    const currentNum = parseFloat(currentValue);
    const result = executeOperation(previousValue, currentNum, operator);
    const formattedResult = formatResult(result);
    const fullExpression = `${previousValue} ${operator} ${currentValue} =`;

    if (formattedResult === 'エラー') {
      setCurrentValue('エラー');
      setExpressionDisplay(fullExpression);
      setPreviousValue(null);
      setOperator(null);
      setWaitingForNewValue(true);
      return;
    }

    // 履歴に追加
    const newRecord: CalculationHistory = {
      id: `${Date.now()}-${Math.random()}`,
      expression: `${previousValue} ${operator} ${currentValue}`,
      result: formattedResult,
    };
    setHistory((prev) => [newRecord, ...prev].slice(0, 30));

    setCurrentValue(formattedResult);
    setExpressionDisplay(fullExpression);
    setPreviousValue(null);
    setOperator(null);
    setWaitingForNewValue(true);
  }, [currentValue, operator, previousValue]);

  // クリア（C / AC）
  const handleClear = useCallback(() => {
    if (currentValue !== '0' && !waitingForNewValue) {
      setCurrentValue('0');
    } else {
      setCurrentValue('0');
      setPreviousValue(null);
      setOperator(null);
      setExpressionDisplay('');
      setWaitingForNewValue(false);
    }
  }, [currentValue, waitingForNewValue]);

  // 履歴クリア
  const handleClearHistory = () => {
    setHistory([]);
  };

  // 履歴選択時の復帰処理
  const handleSelectHistory = (item: CalculationHistory) => {
    setCurrentValue(item.result);
    setExpressionDisplay(`復帰: ${item.expression} =`);
    setWaitingForNewValue(true);
  };

  // キーボードイベントハンドラ
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key >= '0' && e.key <= '9') {
        e.preventDefault();
        handleDigit(e.key);
      } else if (e.key === '.') {
        e.preventDefault();
        handleDecimal();
      } else if (e.key === '+') {
        e.preventDefault();
        handleOperator('+');
      } else if (e.key === '-') {
        e.preventDefault();
        handleOperator('-');
      } else if (e.key === '*') {
        e.preventDefault();
        handleOperator('×');
      } else if (e.key === '/') {
        e.preventDefault();
        handleOperator('÷');
      } else if (e.key === 'Enter' || e.key === '=') {
        e.preventDefault();
        handleEquals();
      } else if (e.key === 'Escape' || e.key === 'c' || e.key === 'C') {
        e.preventDefault();
        handleClear();
      } else if (e.key === '%') {
        e.preventDefault();
        handlePercent();
      } else if (e.key === 'Backspace') {
        e.preventDefault();
        setCurrentValue((prev) => {
          if (waitingForNewValue || prev === 'エラー' || prev.length <= 1) {
            return '0';
          }
          return prev.slice(0, -1);
        });
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleDigit, handleDecimal, handleOperator, handleEquals, handleClear, handlePercent, waitingForNewValue]);

  // C / AC ボタン表示判定
  const clearLabel = currentValue !== '0' && !waitingForNewValue ? 'C' : 'AC';

  return (
    <div className="calculator-container">
      {/* 電卓本体カード */}
      <div className="calculator-card">
        <header className="calculator-header">
          <h1 className="calculator-title">電卓</h1>
        </header>

        {/* ディスプレイパネル */}
        <div className="display-panel">
          <div className="history-text">{expressionDisplay}</div>
          <div className="current-value">{currentValue}</div>
        </div>

        {/* キーパッドグリッド */}
        <div className="keypad-grid">
          <button
            type="button"
            className="btn-calc btn-function"
            onClick={handleClear}
            aria-label={clearLabel === 'C' ? 'クリア' : 'オールクリア'}
          >
            {clearLabel}
          </button>
          <button
            type="button"
            className="btn-calc btn-function"
            onClick={handleToggleSign}
            aria-label="符号反転"
          >
            +/-
          </button>
          <button
            type="button"
            className="btn-calc btn-function"
            onClick={handlePercent}
            aria-label="パーセント"
          >
            %
          </button>
          <button
            type="button"
            className="btn-calc btn-operator"
            onClick={() => handleOperator('÷')}
            aria-label="割る"
          >
            ÷
          </button>

          <button
            type="button"
            className="btn-calc btn-number"
            onClick={() => handleDigit('7')}
          >
            7
          </button>
          <button
            type="button"
            className="btn-calc btn-number"
            onClick={() => handleDigit('8')}
          >
            8
          </button>
          <button
            type="button"
            className="btn-calc btn-number"
            onClick={() => handleDigit('9')}
          >
            9
          </button>
          <button
            type="button"
            className="btn-calc btn-operator"
            onClick={() => handleOperator('×')}
            aria-label="掛ける"
          >
            ×
          </button>

          <button
            type="button"
            className="btn-calc btn-number"
            onClick={() => handleDigit('4')}
          >
            4
          </button>
          <button
            type="button"
            className="btn-calc btn-number"
            onClick={() => handleDigit('5')}
          >
            5
          </button>
          <button
            type="button"
            className="btn-calc btn-number"
            onClick={() => handleDigit('6')}
          >
            6
          </button>
          <button
            type="button"
            className="btn-calc btn-operator"
            onClick={() => handleOperator('-')}
            aria-label="引く"
          >
            -
          </button>

          <button
            type="button"
            className="btn-calc btn-number"
            onClick={() => handleDigit('1')}
          >
            1
          </button>
          <button
            type="button"
            className="btn-calc btn-number"
            onClick={() => handleDigit('2')}
          >
            2
          </button>
          <button
            type="button"
            className="btn-calc btn-number"
            onClick={() => handleDigit('3')}
          >
            3
          </button>
          <button
            type="button"
            className="btn-calc btn-operator"
            onClick={() => handleOperator('+')}
            aria-label="足す"
          >
            +
          </button>

          <button
            type="button"
            className="btn-calc btn-number btn-zero"
            onClick={() => handleDigit('0')}
          >
            0
          </button>
          <button
            type="button"
            className="btn-calc btn-number"
            onClick={handleDecimal}
          >
            .
          </button>
          <button
            type="button"
            className="btn-calc btn-equals"
            onClick={handleEquals}
            aria-label="計算結果"
          >
            =
          </button>
        </div>
      </div>

      {/* 計算履歴パネル */}
      <section className="history-panel" aria-label="計算履歴">
        <div className="history-title">
          <span>計算履歴</span>
          {history.length > 0 && (
            <button
              type="button"
              className="clear-history-btn"
              onClick={handleClearHistory}
            >
              全消去
            </button>
          )}
        </div>

        {history.length === 0 ? (
          <div className="history-empty">
            <p>計算の履歴はまだありません</p>
          </div>
        ) : (
          <ul className="history-list">
            {history.map((item) => (
              <li
                key={item.id}
                className="history-item"
                onClick={() => handleSelectHistory(item)}
                title="クリックしてこの値を電卓にセット"
              >
                <span className="history-expression">{item.expression} =</span>
                <span className="history-result">{item.result}</span>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}
